<template>
  <AppLoader v-if="isLoading" subject="project" />
  <template v-else>
    <AppError
      v-if="error"
      :error="error"
      :title="isNotFound ? 'This opening is no longer listed' : 'Failed to load project'"
      :message="isNotFound ? 'It may have been filled or closed since you received the link.' : undefined"
      :to="isNotFound ? { name: 'join' } : undefined"
      :action-text="isNotFound ? 'See current openings' : undefined"
    />
    <AppEmpty v-else-if="!projectDetails" subject="project details" />
    <section v-else class="flex flex-col gap-10">
      <h1 class="font-semibold text-2xl sm:text-3xl">{{ projectDetails.name }}</h1>
      <section class="flex flex-col gap-4">
        <section class="grid grid-cols-3 gap-4">
          <ApplicationsDetailsDescription class="col-span-3 lg:col-span-2" :description="projectDetails.description" />
          <div class="col-span-3 lg:col-span-1 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-4">
            <ApplicationsDetailsDataItem
              v-for="item in applicationsDetailsDataItems"
              :key="item.label"
              :label="item.label"
              :icon="item.icon"
              :value="item.value"
            />
            <Card>
              <CardContent>
                <NuxtLink v-if="isAuthenticated" :to="{ name: 'applications-id', params: { id: projectDetails.id } }">
                  <Button class="w-full" variant="default">Submit Application</Button>
                </NuxtLink>
                <NuxtLink v-else :to="{ name: 'login' }">
                  <Button class="w-full" variant="default">Log In to Apply</Button>
                </NuxtLink>
              </CardContent>
            </Card>
          </div>
        </section>
      </section>
    </section>
  </template>
</template>

<script setup lang="ts">
import { Calendar, CircleDollarSign, BriefcaseBusiness } from 'lucide-vue-next';
import { getProjectTypeLabel } from '~/constants/projects';
import { getPublicProjectDetails } from '~/client';

const { isAuthenticated } = useUserRole();

definePageMeta({
  layout: 'share',
  auth: false,
});

//TODO: projectDetails.status here is stuffing status. After fixing this, update project name with project status badge

const route = useRoute('share-project-hash');
const projectHash = computed(() => route.params.hash);

const {
  data: projectDetails,
  error,
  isLoading,
} = useQuery({
  key: () => ['share.project.hash', projectHash.value],
  query: () => getPublicProjectDetails({ composable: '$fetch', path: { public_hash: projectHash.value } }),
  enabled: () => !!projectHash.value,
});

useHead({
  title: computed(() => projectDetails.value?.name ?? 'Project'),
});

//TODO: Can't throw 404 error from query, so we handle it here
// A recruit arrives here from a link in a text, and the project can have public sharing switched off after
// that text is sent - the link is already on their phone and cannot be recalled. The state has to render
// here rather than raise: a fatal error routes to the global 404, whose only action lands a logged-out
// visitor on /login, an account they do not have, so the campaign's call to action would dead-end. Saying
// what happened in place also reads correctly for an admin checking a link they think is broken.
const isNotFound = computed(() => error.value?.statusCode === 404);

const applicationsDetailsDataItems = computed(() => {
  if (!projectDetails.value) return [];
  return [
    {
      label: 'Type',
      value: getProjectTypeLabel(projectDetails.value.type),
      icon: BriefcaseBusiness,
    },
    {
      label: 'Duration',
      value: `${startEndDate(projectDetails.value.start_date, projectDetails.value.end_date)}`,
      icon: Calendar,
    },
    {
      label: `Payment per ${isUpcomingSignatureProjectPricing(projectDetails.value.pricing) ? 'Signature' : 'Hour'}`,
      value: upcomingProjectPricing(projectDetails.value.pricing),
      icon: CircleDollarSign,
    },
  ];
});
</script>

<style scoped lang="scss"></style>
